// Dockerfile for Spring Boot application
FROM eclipse-temurin:17-jre-alpine
WORKDIR /app
COPY target/order-service-1.0.0.jar app.jar
EXPOSE 8080
ENTRYPOINT ["java", "-jar", "app.jar"]

// Starting the container shares the host kernel
// docker run -p 8080:8080 order-service
// Container starts in ~2 seconds, uses ~200MB RAM

// Compare to VM approach:
// - Install full Ubuntu/CentOS (1.5-2GB)
// - Install JDK (300-500MB)
// - Copy application JAR
// - Configure systemd service
// - Boot VM (30-45 seconds)
// Total: 2-4GB RAM, 30-60s startup

// OrderService running in Container A
@Service
public class OrderService {
    private final ProcessHandle currentProcess = ProcessHandle.current();

    public String getContainerInfo() {
        var pid = currentProcess.pid();
        var hostname = System.getenv("HOSTNAME"); // Container ID
        var cpuLimit = Runtime.getRuntime().availableProcessors();

        // This container thinks it's PID 1, isolated from others
        return String.format(
            "Running as PID %d in container %s with %d CPUs",
            pid, hostname, cpuLimit
        );
    }
}

// Container A sees: PID 1, hostname=3f2a8b9c, 2 CPUs
// Container B sees: PID 1, hostname=7d4e1f5a, 2 CPUs
// Host kernel sees: PID 12847 (A) and PID 13092 (B)
// Each container has isolated view via PID and UTS namespaces
